public class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT_BASE = 'callout:FB_Exchange_Rates/v1/latest';

    private static final Pattern VALID_CODE = Pattern.compile('[A-Z]{3}');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {

        // --- Validate & normalise base currency (no callout on failure) ---
        String base = normalise(baseCurrency);
        if (!isValidCurrencyCode(base)) {
            throw new ExchangeRateException(
                'Invalid base currency code: ' + (baseCurrency == null ? 'null' : baseCurrency));
        }

        // --- Validate & normalise quote currencies (no callout on failure) ---
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set is null or empty');
        }

        Set<String> normalisedQuotes = new Set<String>();
        for (String raw : quoteCurrencies) {
            String code = normalise(raw);
            if (!isValidCurrencyCode(code)) {
                throw new ExchangeRateException(
                    'Invalid quote currency code: ' + (raw == null ? 'null' : raw));
            }
            normalisedQuotes.add(code);
        }

        // --- Build the request URL ---
        String symbols = String.join(new List<String>(normalisedQuotes), ',');
        String endpoint = ENDPOINT_BASE + '?base=' + base + '&symbols=' + symbols;

        HttpRequest req = buildRequest(endpoint);
        Http http = new Http();

        HttpResponse res;
        try {
            res = http.send(req);
        } catch (Exception e) {
            throw new ExchangeRateException('Callout failed: ' + e.getMessage());
        }

        // --- Retry once on 503 ---
        if (res.getStatusCode() == 503) {
            req = buildRequest(endpoint);
            try {
                res = http.send(req);
            } catch (Exception e) {
                throw new ExchangeRateException(
                    'Callout failed on retry: ' + e.getMessage());
            }
        }

        // --- Status check (after retry) ---
        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'HTTP status ' + res.getStatusCode() + ' from exchange-rate API');
        }

        // --- Parse body ---
        String body = res.getBody();
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Empty response body from exchange-rate API');
        }

        Map<String, Object> parsed;
        try {
            Object deserialized = JSON.deserializeUntyped(body);
            if (deserialized instanceof Map<String, Object>) {
                parsed = (Map<String, Object>) deserialized;
            } else {
                throw new ExchangeRateException('Unable to parse response body: not a JSON object');
            }
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse response body: ' + e.getMessage());
        }

        Object ratesObj = parsed.get('rates');
        if (!(ratesObj instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Response body missing or invalid "rates" object');
        }
        Map<String, Object> rates = (Map<String, Object>) ratesObj;

        // --- Build result map ---
        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : normalisedQuotes) {
            if (!rates.containsKey(code)) {
                throw new ExchangeRateException('No rate returned for ' + code);
            }
            Object rateVal = rates.get(code);
            if (rateVal == null) {
                throw new ExchangeRateException('Invalid or missing rate for ' + code);
            }
            Decimal rate;
            if (rateVal instanceof Decimal) {
                rate = (Decimal) rateVal;
            } else if (rateVal instanceof Integer) {
                rate = (Decimal) rateVal;
            } else {
                try {
                    rate = (Decimal) JSON.deserialize(String.valueOf(rateVal), Decimal.class);
                } catch (Exception e) {
                    throw new ExchangeRateException('Invalid or missing rate for ' + code);
                }
            }
            result.put(code, rate);
        }

        return result;
    }

    // ─── Private helpers ───────────────────────────────────────────────────────

    private static HttpRequest buildRequest(String endpoint) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        req.setTimeout(60000);
        return req;
    }

    private static String normalise(String s) {
        if (s == null) return null;
        return s.trim().toUpperCase();
    }

    private static Boolean isValidCurrencyCode(String s) {
        return s != null && s.length() == 3 && VALID_CODE.matcher(s).matches();
    }
}
