public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku { get; set; }
        public Integer quantity { get; set; }
        public Decimal unitPrice { get; set; }
        public Decimal discount { get; set; }
        public Decimal lineTotal { get; set; }

        public Line() {
            this.sku = '';
            this.quantity = 0;
            this.unitPrice = Decimal.valueOf(0);
            this.discount = Decimal.valueOf(0);
            this.lineTotal = Decimal.valueOf(0);
        }
    }

    public class Order {
        public String orderNumber { get; set; }
        public Date orderDate { get; set; }
        public String currencyCode { get; set; }
        public String customerEmail { get; set; }
        public List<Line> lines { get; set; }
        public Decimal total { get; set; }

        public Order() {
            this.orderNumber = '';
            this.orderDate = null;
            this.currencyCode = '';
            this.customerEmail = null;
            this.lines = new List<Line>();
            this.total = Decimal.valueOf(0);
        }
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON');
        }

        if (parsed == null || !(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body is not a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        // --- Validate number ---
        if (!root.containsKey('number') || String.isBlank((String) root.get('number'))) {
            throw new PayloadException('Missing or blank order number');
        }

        Order order = new Order();
        order.orderNumber = (String) root.get('number');

        // --- date (optional) ---
        if (root.containsKey('date') && root.get('date') instanceof String) {
            String dateStr = (String) root.get('date');
            if (String.isNotBlank(dateStr)) {
                try {
                    order.orderDate = Date.valueOf(dateStr);
                } catch (Exception e) {
                    // leave null if date string is not parseable
                }
            }
        }

        // --- currency (optional) ---
        if (root.containsKey('currency') && root.get('currency') instanceof String) {
            order.currencyCode = (String) root.get('currency');
        }

        // --- customer (optional, may be missing or malformed) ---
        if (root.containsKey('customer') && root.get('customer') instanceof Map<String, Object>) {
            Map<String, Object> cust = (Map<String, Object>) root.get('customer');
            if (cust.containsKey('email') && cust.get('email') instanceof String) {
                order.customerEmail = (String) cust.get('email');
            }
        }

        // --- lines ---
        order.lines = new List<Line>();
        if (root.containsKey('lines') && root.get('lines') instanceof List<Object>) {
            List<Object> rawLines = (List<Object>) root.get('lines');
            for (Object item : rawLines) {
                if (!(item instanceof Map<String, Object>)) {
                    continue;
                }
                Map<String, Object> lineMap = (Map<String, Object>) item;

                // Validate sku
                if (!lineMap.containsKey('sku') || lineMap.get('sku') == null || String.isBlank((String) lineMap.get('sku'))) {
                    throw new PayloadException('Line has missing sku');
                }

                // Validate quantity
                if (!lineMap.containsKey('quantity') || lineMap.get('quantity') == null) {
                    throw new PayloadException('Line has missing or non-positive quantity');
                }
                Decimal qtyD = toDecimal(lineMap.get('quantity'));
                if (qtyD == null || qtyD <= 0) {
                    throw new PayloadException('Line has missing or non-positive quantity');
                }

                // Validate unitPrice
                if (!lineMap.containsKey('unitPrice') || lineMap.get('unitPrice') == null) {
                    throw new PayloadException('Line has missing unitPrice');
                }
                Decimal priceD = toDecimal(lineMap.get('unitPrice'));
                if (priceD == null || priceD < 0) {
                    throw new PayloadException('Line has missing or negative unitPrice');
                }

                // discount (missing or null → 0)
                Decimal disc = Decimal.valueOf(0);
                if (lineMap.containsKey('discount') && lineMap.get('discount') != null) {
                    disc = toDecimal(lineMap.get('discount'));
                    if (disc == null) {
                        disc = Decimal.valueOf(0);
                    }
                }

                // Build Line
                Line line = new Line();
                line.sku = (String) lineMap.get('sku');
                line.quantity = qtyD.intValue();
                line.unitPrice = priceD;
                line.discount = disc;

                // lineTotal = quantity × unitPrice × (1 − discount), 2 dp, HALF_UP
                Decimal total = qtyD * priceD * (Decimal.valueOf(1) - disc);
                line.lineTotal = total.setScale(2, System.RoundingMode.HALF_UP);

                order.lines.add(line);
            }
        }

        // --- total = sum of line totals (0 when empty) ---
        order.total = Decimal.valueOf(0);
        for (Line l : order.lines) {
            order.total = order.total + l.lineTotal;
        }

        return order;
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines != null ? order.lines.size() : 0);
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }

    private static Decimal toDecimal(Object obj) {
        if (obj == null) return null;
        if (obj instanceof Integer) return Decimal.valueOf((Integer) obj);
        if (obj instanceof Decimal) return (Decimal) obj;
        if (obj instanceof Long) return Decimal.valueOf(((Long) obj).intValue());
        if (obj instanceof Double) return Decimal.valueOf((Double) obj);
        return null;
    }
}
