public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception { }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {

        // --- validate inputs -----------------------------------------------------------
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object or field API name is null or blank.');
        }

        // --- resolve object (case-insensitive) -----------------------------------------
        Schema.SObjectType sType = resolveObjectType(objectApiName);
        if (sType == null) {
            throw new PicklistServiceException('Object ' + objectApiName + ' does not exist.');
        }

        // --- resolve field (case-insensitive) ------------------------------------------
        Schema.DescribeSObjectResult sTypeDesc = sType.getDescribe();

        // fields.getMap() keys are lowercase by default; try exact and lower-case
        Map<String, Schema.SObjectField> fieldMap = sTypeDesc.fields.getMap();
        if (fieldMap == null || fieldMap.isEmpty()) {
            throw new PicklistServiceException('Field ' + fieldApiName + ' does not exist on object ' + objectApiName + '.');
        }

        Schema.SObjectField sField = fieldMap.get(fieldApiName.toLowerCase());
        if (sField == null) {
            // fallback: case-insensitive scan (safety net for custom objects)
            for (String key : fieldMap.keySet()) {
                if (key.equalsIgnoreCase(fieldApiName)) {
                    sField = fieldMap.get(key);
                    break;
                }
            }
        }

        if (sField == null) {
            throw new PicklistServiceException('Field ' + fieldApiName + ' does not exist on object ' + objectApiName + '.');
        }

        Schema.DescribeFieldResult fieldDesc = sField.getDescribe();
        if (fieldDesc == null) {
            throw new PicklistServiceException('Field ' + fieldApiName + ' does not exist on object ' + objectApiName + '.');
        }

        // --- type guard ----------------------------------------------------------------
        Schema.DisplayType dt = fieldDesc.getType();
        if (dt != Schema.DisplayType.PICKLIST && dt != Schema.DisplayType.MULTISELECTPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' on object ' + objectApiName + ' is not a picklist or multi-select picklist.'
            );
        }

        // --- build result list ---------------------------------------------------------
        List<PicklistService.Option> options = new List<PicklistService.Option>();
        List<Schema.PicklistEntry> entries = fieldDesc.getPickListValues();

        if (entries != null) {
            for (Schema.PicklistEntry pe : entries) {
                if (pe == null || !pe.isActive()) {
                    continue;
                }

                String label = pe.getLabel();
                if (String.isBlank(label)) {
                    label = pe.getValue();
                }

                options.add(new PicklistService.Option(pe.getValue(), label, pe.isDefaultValue()));
            }
        }

        return options;
    }

    // ---- private helpers --------------------------------------------------------------

    private static Schema.SObjectType resolveObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDesc = Schema.getGlobalDescribe();

        // direct lookups (exact → upper → lower)
        Schema.SObjectType st = globalDesc.get(objectApiName);
        if (st != null) { return st; }

        st = globalDesc.get(objectApiName.toUpperCase());
        if (st != null) { return st; }

        st = globalDesc.get(objectApiName.toLowerCase());
        if (st != null) { return st; }

        // last-resort case-insensitive scan
        for (String key : globalDesc.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                return globalDesc.get(key);
            }
        }

        return null;
    }
}
