public without sharing class LogPurgeJob implements Schedulable {

    private static final Integer CHUNK_SIZE = 10000;

    public LogPurgeJob() {}

    public void execute(SchedulableContext sc) {
        Datetime cutoff30  = Datetime.now().addDays(-30);
        Datetime cutoff180 = Datetime.now().addDays(-180);

        // Non-ERROR logs (including blank/null Level__c) older than 30 days
        List<FB_Integration_Log__c> toDelete = [
            SELECT Id FROM FB_Integration_Log__c
            WHERE CreatedDate < :cutoff30
              AND (Level__c != 'ERROR' OR Level__c = NULL)
        ];

        // ERROR logs older than 180 days
        toDelete.addAll([
            SELECT Id FROM FB_Integration_Log__c
            WHERE CreatedDate < :cutoff180
              AND Level__c = 'ERROR'
        ]);

        if (toDelete.isEmpty()) {
            return;
        }

        // Process in chunks to stay within the 50 000-row DML limit
        Integer idx = 0;
        while (idx < toDelete.size()) {
            Integer endIdx = Math.min(idx + CHUNK_SIZE, toDelete.size());
            List<FB_Integration_Log__c> chunk = toDelete.subList(idx, endIdx);
            delete chunk;
            Database.emptyRecycleBin(chunk);
            idx = endIdx;
        }
    }

    public static Id scheduleNightly() {
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
