public class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        // Seed every requested account with 0 so the map never has a null value
        // and every requested Id is guaranteed to be a key.
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            result.put(accountId, 0);
        }

        // Current-calendar-year boundaries (inclusive).
        Date today = Date.today();
        Integer yr = today.year();
        Date yearStart = Date.newInstance(yr, 1, 1);
        Date yearEnd   = Date.newInstance(yr, 12, 31);

        // Single aggregate SOQL – sums happen in the database, not in Apex.
        // WITH SECURITY_ENFORCED enforces FLS and sharing for the running user.
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE IsWon = true
              AND AccountId IN :accountIds
              AND CloseDate >= :yearStart
              AND CloseDate <= :yearEnd
            GROUP BY AccountId
            WITH SECURITY_ENFORCED
        ]) {
            Id accId = (Id) ar.get('AccountId');
            if (accId == null) { continue; }

            Decimal total = (Decimal) ar.get('totalAmount');
            // If every qualifying Amount was blank the SUM returns null → default to 0.
            result.put(accId, total != null ? total : 0);
        }

        return result;
    }
}
