public with sharing class Application {

    /**
     * Service factory – maps each service interface Type to its implementation Type.
     */
    public static fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory(
            new Map<Type, Type> {
                IAccountsService.Class => AccountsServiceImpl.class
            }
        );

    /**
     * Selector factory – maps each SObjectType to its selector instance.
     */
    public static fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory(
            new Map<SObjectType, fflib_ISObjectSelector> {
                Account.SObjectType => new AccountsSelector(),
                Contact.SObjectType => new ContactsSelector()
            }
        );

    /**
     * Domain factory – maps each SObjectType to the Type of its domain
     * IConstructable class.
     */
    public static fflib_Application.DomainFactory Domain =
        new fflib_Application.DomainFactory(
            new Map<SObjectType, Type> {
                Account.SObjectType => Accounts.Constructor.class
            }
        );

    /**
     * UnitOfWork factory – declares the SObject types that participate in a
     * single unit of work, listed in parent→child / dependency order so that
     * one commitWork() can insert Accounts first, then their child Contacts
     * and Opportunities, then OpportunityContactRoles that link the newly-
     * created Opportunities and Contacts.
     */
    public static fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(
            new SObjectType[] {
