public with sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opps =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opps) {
            if (opp.StageName != 'Closed Won') {
                toClose.add(opp);
            }
        }
        if (toClose.isEmpty()) {
            return 0;
        }

        // Obtain a single fflib Unit of Work for the entire transaction
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        List<Deal_Won__e> events = new List<Deal_Won__e>();

        for (Opportunity opp : toClose) {
            opp.StageName = 'Closed Won';
            opp.CloseDate = Date.today();
            uow.registerDirty(opp);
            events.add(new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c         = opp.Amount
            ));
        }

        // commit() executes all registered DML atomically (all-or-none).
        // If any update fails, the exception propagates to the caller and
        // EventBus.publish is never reached – no Deal_Won__e is published.
        uow.commit();

        // Platform events are published only after the DML has been committed
        // successfully; a failure above short-circuits past this line.
        if (!events.isEmpty()) {
            EventBus.publish(events);
        }

        return toClose.size();
    }
}
