```java
/**
 * ErpCustomerSync
 *
 * Asynchronous (Future) helper that serialises Account records into the
 * JSON array the ERP /api/customers endpoint expects and POSTs them.
 *
 * Contract
 *   POST callout:ERP/api/customers
 *   Content-Type: application/json
 *   Body: [{"salesforceId":"001xxxxxxxxxxxxxxx","name":"...","country":"..."}]
 *
 * salesforceId is always 18 characters (15 + 3-char checksum).
 * country is null when BillingCountry is blank.
 *
 * Error handling and retries are out of scope for this ticket.
 */
public with sharing class ErpCustomerSync {

    private static final Integer MAX_BATCH = 200;

    // ──────────────────────────────────────────────────────────────────────
    //  Entry point – called from AccountTrigger (after insert)
    // ──────────────────────────────────────────────────────────────────────
    @future(callout = true)
    public static void pushToErp(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Re-query to obtain current, committed field values.
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :accountIds
            LIMIT :MAX_BATCH
        ];

        if (accounts.isEmpty()) {
            return;
        }

        // ── Build JSON payload ────────────────────────────────────────────
        List<Map<String, Object>> payload = new List<Map<String, Object>>();

        for (Account acc : accounts) {
            payload.add(new Map<String, Object>{
                'salesforceId' => to18CharId(acc.Id),
                'name'         => acc.Name,
                'country'      => String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry
            });
        }

        // ── Execute callout ───────────────────────────────────────────────
        Http        http = new Http();
        HttpRequest req  = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(payload));

        // 202 Accepted = success.  Other statuses: out of scope.
        http.send(req);
    }

    // ──────────────────────────────────────────────────────────────────────
    //  Convert the 15-character Id (Apex internal representation) to the
    //  18-character case-insensitive form expected by the ERP.
    //
    //  Algorithm (three 5-character groups):
    //    For each group of 5 characters, build a 5-bit mask.
    //    Bit i (0-4) is set when the character at that position is an
    //    uppercase letter (A-Z).
    //    Map mask 0-25 → A-Z,  mask 26-31 → 0-5.
    // ──────────────────────────────────────────────────────────────────────
    @TestVisible
    private static String to18CharId(Id recordId) {
        if (recordId == null) {
            return null;
        }

        String id15 = String.valueOf(recordId);
        if (id15.length() != 15) {
            return id15; // already 18-char or unexpected – pass through
        }

        final String ALPHANUM = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
        // Lookup: mask < 26 → A-Z,  mask >= 26 → 0-5
        final String DIGITS   = '0123456789';

        // Powers-of-2 helper to avoid Math.pow / Decimal rounding
        final Integer[] POW2  = new Integer[]{ 1, 2, 4, 8, 16 };

        String checksum = '';

        for (Integer g = 0; g < 3; g++) {
            Integer mask = 0;

            for (Integer i = 0; i < 5; i++) {
                Integer idx = g * 5 + i;
                String  ch  = id15.substring(idx, idx + 1);

                // Is the character an uppercase letter?
                // Uppercase letters differ from their lowercase form
                // AND equal their uppercase form.
                if (ch == ch.toUpperCase() && ch != ch.toLowerCase()) {
                    mask += POW2[i];
                }
            }

            if (mask < 26) {
                checksum += ALPHANUM.substring(mask, mask + 1);
            } else {
                checksum += DIGITS.substring(mask - 26, mask - 26 + 1);
            }
        }

        return id15 + checksum;
    }
}
