// RenewalReminderService.cls
//
// ⚠ GOVERNOR-LIMIT WARNING ⚠
// Salesforce enforces a hard limit of 10 Messaging.sendEmail() invocations per
// transaction.  Because this method places one sendEmail() call per opportunity
// *inside* the loop, any batch larger than 10 opportunities will throw a
// LimitException on the 11th call, aborting the entire transaction.  For the
// 200-per-batch scenario, either batch the emails into groups of ≤ 10 before
// calling this method, or accumulate messages into a single List<SingleEmailMessage>
// and issue one Messaging.sendEmail(messages, false) call (the per-message
// SendEmailResult[].isSuccess() check still gives you per-email fault isolation).
// The code below follows the requested one-call-per-opportunity design.

public with sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Bulk-safe SOQL – never inside a loop
        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM   Opportunity
            WHERE  Id IN :opportunityIds
            LIMIT  200
        ];

        Integer successCount = 0;

        for (Opportunity opp : opps) {
            // Only User records (Id prefix 005…) are valid targets for
            // setTargetObjectId; skip Queue / Team-managed records.
            if (opp.OwnerId == null ||
                !String.valueOf(opp.OwnerId).startsWith('005')) {
                continue;
            }

            Messaging.SingleEmailMessage msg = new Messaging.SingleEmailMessage();
            msg.setTargetObjectId(opp.OwnerId);
            msg.setSaveAsActivity(false);
            msg.setSubject('Renewal due: ' + opp.Name);
            msg.setPlainTextBody(
                'Hello,\\n\\nA renewal is due for opportunity "' + opp.Name
                + '".\\n\\n  Close date : ' + opp.CloseDate
                + '\\n\\nPlease review and take any necessary action before the close date.\\n\\n-- Renewal Reminder Bot'
            );

            Messaging.SendEmailResult[] results =
                Messaging.sendEmail(new Messaging.SingleEmailMessage[] { msg }, false);

            if (results[0].isSuccess()) {
                successCount++;
            }
        }

        return successCount;
    }
}
