```java
/**
 * Service for setting a Contact's current primary employer (Organization Account)
 * under NPSP (Household Account model, Affiliations enabled).
 *
 * For each Contact in the input map (where the org is NOT already the primary):
 *   1. Creates a new npe5__Affiliation__c (Status = Current, Primary = true)
 *      linking the Contact to the Organization Account.
 *   2. Updates Contact.npsp__Primary_Affiliation__c to point to that Organization.
 *
 * If the org is already the Contact's primary affiliation (lookup matches),
 * the Contact is left completely untouched — no duplicate affiliation, no DML.
 *
 * NPSP's own trigger logic retires the *previous* primary affiliation (sets it
 * to Former, non-primary, end-date = today) as part of its standard mechanism.
 *
 * Governor budget: ≤ 2 SOQL, ≤ 2 DML regardless of input size (tested to 200).
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        // ── guard clauses ─────────────────────────────────────────────────────
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Build a clean working map; skip null values.
        Map<Id, Id> valid = new Map<Id, Id>();
        for (Id cId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(cId);
            if (orgId != null && cId != null) {
                valid.put(cId, orgId);
            }
        }
        if (valid.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>(valid.keySet());
        Set<Id> orgIds     = new Set<Id>(valid.values());

        // ── SOQL 1: Contacts (primary affiliation lookup + household) ─────────
        Map<Id, Contact> contactMap = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c, AccountId
            FROM   Contact
            WHERE  Id IN :contactIds
        ]);

        // ── SOQL 2: existing Current Affiliations for these pairs ────────────
        //    Used to detect "already linked" and prevent duplicate affiliations.
        Map<String, npe5__Affiliation__c> existingAffByPair = new Map<String, npe5__Affiliation__c>();

        for (npe5__Affiliation__c a : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c,
                   npe5__Primary__c, npe5__Status__c
            FROM   npe5__Affiliation__c
            WHERE  npe5__Contact__c      IN :contactIds
              AND  npe5__Organization__c  IN :orgIds
              AND  npe5__Status__c        = 'Current'
        ]) {
            String pairKey = a.npe5__Contact__c + '-' + a.npe5__Organization__c;
            existingAffByPair.put(pairKey, a);
        }

        // ── Build the work lists (no DML yet) ────────────────────────────────
        List<npe5__Affiliation__c> affsToInsert = new List<npe5__Affiliation__c>();
        List<Contact>              contactsToUpd = new List<Contact>();

        for (Id cId : valid.keySet()) {
            Id orgId = valid.get(cId);

            Contact c = contactMap.get(cId);
            if (c == null) {
                continue; // Contact doesn't exist; skip.
            }

            // Already primary → nothing changes.
            if (c.npsp__Primary_Affiliation__c == orgId) {
                continue;
            }

            // Already has a Current/Primary affiliation to this org → skip (no dup).
            String pairKey = cId + '-' + orgId;
            if (existingAffByPair.containsKey(pairKey)) {
                npe5__Affiliation__c existing = existingAffByPair.get(pairKey);
                if (existing.npe5__Primary__c == true) {
                    continue;
                }
            }

            // ── Create the new affiliation ────────────────────────────────────
            npe5__Affiliation__c newAff = new npe5__Affiliation__c();
            newAff.npe5__Contact__c      = cId;
            newAff.npe5__Organization__c = orgId;
            newAff.npe5__Status__c       = 'Current';
            newAff.npe5__Primary__c      = true;
            newAff.npe5__StartDate__c    = Date.today();
            affsToInsert.add(newAff);

            // ── Update the Contact's primary affiliation lookup ───────────────
            c.npsp__Primary_Affiliation__c = orgId;
            contactsToUpd.add(c);
        }

        // ── DML (at most 2 statements) ───────────────────────────────────────
        if (!affsToInsert.isEmpty()) {
            insert affsToInsert;   // DML 1 – triggers create new + retire old
        }
        if (!contactsToUpd.isEmpty()) {
            update contactsToUpd;  // DML 2 – re-point primary lookup to new org
        }
    }
}
