/**
 * Service to create Enhanced Recurring Donation (npe03__Recurring_Donation__c) records
 * from monthly-giving sign-up form submissions.
 */
public class RecurringGiftService {

    // ──────────────────────────────────────────────────────────────
    //  Custom exception
    // ──────────────────────────────────────────────────────────────
    public class RecurringGiftException extends Exception {}

    // ──────────────────────────────────────────────────────────────
    //  Value-object that mirrors the form payload
    // ──────────────────────────────────────────────────────────────
    public class GiftRequest {
        public Id     contactId;      // donor Contact
        public Decimal amount;        // per-installment amount
        public Integer dayOfMonth;    // 1-31 (31 = "last day of month")
        public Date    startDate;     // first-gift date
        public Integer installments;  // null / 0 ⇒ open-ended
        public String  paymentMethod; // 'Credit Card', 'ACH', 'Check'
    }

    // ──────────────────────────────────────────────────────────────
    //  Entry point
    // ──────────────────────────────────────────────────────────────
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {

        // ── Guard: null / empty input ─────────────────────────────
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // ── Pass 1 – validate (no DML / SOQL yet) ────────────────
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];

            if (req.contactId == null) {
                throw new RecurringGiftException(
                    'Request ' + i + ': Contact Id is required.');
            }

            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException(
                    'Request ' + i + ': Amount must be greater than zero.');
            }

            if (req.dayOfMonth == null ||
                req.dayOfMonth < 1 ||
                req.dayOfMonth > 31) {
                throw new RecurringGiftException(
                    'Request ' + i + ': Day of Month must be between 1 and 31.');
            }

            if (req.startDate == null) {
                throw new RecurringGiftException(
                    'Request ' + i + ': Start Date is required.');
            }
        }

        // ── Pass 2 – build Recurring Donation records ─────────────
        List<npe03__Recurring_Donation__c> rds =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {

            npe03__Recurring_Donation__c rd =
                new npe03__Recurring_Donation__c();

            // Donor
            rd.npe03__Contact__c  = req.contactId;

            // Per-installment amount
            rd.npe03__Amount__c   = req.amount;

            // Monthly cadence – every 1 month
            rd.npe03__Installment_Period__c  = 'Monthly';
            rd.npsp__InstallmentFrequency__c  = '1';

            // Day-of-month scheduling (field is a String in NPSP)
            if (req.dayOfMonth == 31) {
                rd.npsp__Day_of_Month__c                  = '31';
                rd.npsp__Always_Use_Last_Day_Of_Month__c  = true;
            } else {
                rd.npsp__Day_of_Month__c                  = String.valueOf(req.dayOfMonth);
                rd.npsp__Always_Use_Last_Day_Of_Month__c  = false;
            }

            // Dates
            rd.npsp__StartDate__c            = req.startDate;
            rd.npe03__Date_Established__c    = req.startDate;
            rd.npe03__Next_Payment_Date__c   = req.startDate;

            // Status
            rd.npsp__Status__c = 'Active';

            // Payment method as supplied
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            // Recurring type
            rd.npsp__RecurringType__c = 'Recurring';

            // Schedule type (Aligned ⇒ payments align to the chosen day)
            rd.npe03__Schedule_Type__c = 'Aligned';

            // Open-ended vs. fixed-length
            if (req.installments == null || req.installments == 0) {
                // Open-ended – keep recurring until manually stopped
                rd.npe03__Open_Ended_Status__c = 'Active';
                // Leave npe03__Installments__c null (unbounded)
            } else {
                // Fixed-length – finite number of installments
                rd.npe03__Installments__c = req.installments;
                // Do not set Open_Ended_Status__c (null ⇒ fixed-length)
            }

            rds.add(rd);
        }

        // ── Pass 3 – single DML (bulk-safe, one statement) ────────
        insert rds;

        // ── Collect Ids in request order ─────────────────────────
        List<Id> ids = new List<Id>(rds.size());
        for (npe03__Recurring_Donation__c rd : rds) {
            ids.add(rd.Id);
        }

        return ids;
    }
}
