public class HouseholdService {

    public static Id createHousehold(List<Contact> members) {

        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Resolve the household record-type Id dynamically – never hard-code it.
        Id hhRtId = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
            .get('HH_Account')
            .getRecordTypeId();

        // 1. Create the household Account.
        //    Name is required at the platform level, so we supply a placeholder;
        //    NPSP's automatic household-naming automation (trigger/flow on the
        //    linked Contacts) will overwrite it with the generated family name.
        Account hh = new Account();
        hh.RecordTypeId = hhRtId;
        hh.Name = 'Temporary';

        insert hh;

        // 2. Associate every new contact with the household, then insert in one DML.
        //    This is what triggers NPSP to regenerate the household greeting/name.
        for (Contact c : members) {
            c.AccountId = hh.Id;
        }
        insert members;

        // 3. Set the first contact as the household's primary contact.
        //    Use a fresh SObject so we touch only that one field and don't
        //    accidentally overwrite anything a trigger may have changed on
        //    the Account during the Contact insert.
        update new Account(
            Id = hh.Id,
            npe01__One2OneContact__c = members[0].Id
        );

        return hh.Id;
    }
}
