/**
 * Records a Closed Won donation (gift) in the NPSP Household Account model.
 *
 * NPSP behaviour: setting npsp__Primary_Contact__c on an Opportunity causes
 * NPSP automation to auto-create a "Donor" Contact Role for that contact.
 * We therefore only create the "Household Member" roles for the *other*
 * household members – creating a "Donor" role manually would result in a
 * duplicate Contact Role for the primary contact.
 */
public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {

        // ── Validation ──────────────────────────────────────────────────────
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be a positive value.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM   Contact
            WHERE  Id = :contactId
            LIMIT  1
        ];

        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        Contact primaryContact = contacts[0];

        // ── Retrieve the household account (the Contact's Account in
        //    the NPSP Household Account model) ──────────────────────────────
        Id householdAccountId = primaryContact.AccountId;

        // ── Gather every OTHER member of the household (exclude the
        //    primary donor so no contact receives two roles) ────────────────
        List<Contact> householdMembers = [
            SELECT Id
            FROM   Contact
            WHERE  AccountId = :householdAccountId
              AND  Id != :contactId
        ];

        // ── Build Opportunity ───────────────────────────────────────────────
        String dateStr = String.valueOf(giftDate); // yyyy-MM-dd
        String oppName = primaryContact.FirstName + ' ' + primaryContact.LastName
                       + ' Donation ' + dateStr;

        Opportunity opp = new Opportunity(
            Name                     = oppName,
            AccountId                = householdAccountId,
            Amount                   = amount,
            CloseDate                = giftDate,
            StageName                = 'Closed Won',
            Type                     = 'Donation',
            npsp__Primary_Contact__c = contactId   // NPSP auto-creates the "Donor" Contact Role
        );
        insert opp;

        // ── Build Contact Roles (Household Member only; Donor is auto-created
        //    by NPSP when npsp__Primary_Contact__c is set) ──────────────────
        if (!householdMembers.isEmpty()) {
            List<OpportunityContactRole> roles = new List<OpportunityContactRole>();

            for (Contact member : householdMembers) {
                roles.add(new OpportunityContactRole(
                    OpportunityId = opp.Id,
                    ContactId     = member.Id,
                    Role          = 'Household Member',
                    IsPrimary     = false
                ));
            }

            insert roles;
        }

        // ── Build the single Payment ────────────────────────────────────────
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c    = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c   = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c           = true
        );
        insert payment;

        return opp.Id;
    }
}
