/**
 * TDTM handler that creates a "Major gift thank-you call" Task whenever an
 * Opportunity qualifies as a major gift (Closed Won, Amount >= 5000).
 *
 * Trigger Handler registration:
 *   Class        : OPP_MajorGiftFollowUp_TDTM
 *   Object       : Opportunity
 *   Trigger Action: AfterInsert;AfterUpdate
 *   Load Order   : 5
 *   Is Async     : false
 */
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    /**
     * Override to keep execution synchronous (Trigger Handler "Is Async" unchecked).
     */
    public override Boolean isAsync() {
        return false;
    }

    /**
     * Core TDTM entry point called by the NPSP TDTM dispatcher.
     */
    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {

        // Guard: nothing to do if the new-map is empty
        if (newlist == null || newlist.isEmpty()) {
            return null;
        }

        List<Task> tasksToInsert = new List<Task>();

        // ---------- AfterInsert ----------
        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (Integer i = 0; i < newlist.size(); i++) {
                Opportunity opp = (Opportunity) newlist[i];

                if (isQualified(opp)) {
                    tasksToInsert.add(buildTask(opp));
                }
            }
        }
        // ---------- AfterUpdate ----------
        else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            for (Integer i = 0; i < newlist.size(); i++) {
                Opportunity newOpp = (Opportunity) newlist[i];
                Opportunity oldOpp = (Opportunity) oldlist[i];

                Boolean nowQualified   = isQualified(newOpp);
                Boolean wasQualified   = isQualified(oldOpp);

                // Fire only when the opportunity *becomes* qualified
                if (nowQualified && !wasQualified) {
                    tasksToInsert.add(buildTask(newOpp));
                }
            }
        }

        // Single DML call for all qualifying opportunities (up to 200 in a batch)
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return null;
    }

    // ---------------------------------------------------------------
    //  Private helpers
    // ---------------------------------------------------------------

    /**
     * Returns true when the opportunity is Closed Won AND Amount >= 5000.
     * Uses the snapshot's values so old/new comparison works correctly.
     */
    private Boolean isQualified(Opportunity opp) {
        return opp.StageName == 'Closed Won' && opp.Amount >= 5000;
    }

    /**
     * Builds the thank-you Task for a qualifying Opportunity.
     */
    private Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject      = 'Major gift thank-you call';
        t.Priority     = 'High';
        t.Status       = 'Not Started';
        t.WhatId       = opp.Id;
        t.WhoId        = opp.npsp__Primary_Contact__c;   // may be null
