```apex
/**
 * Trigger Action – prevents two Contacts on the same Account from sharing an e-mail
 * (case-insensitive). Registered via Trigger_Action__mdt for before-insert and
 * before-update on Contact.
 *
 * Bulk-safe: one SOQL query per execution, works for up to 200 records.
 * Partial-save friendly: addError (not exception) so valid rows in the same DML survive.
 */
public with sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUP_MSG =
        'Another contact on this account already uses this email address.';

    // ── TriggerAction.BeforeInsert ──────────────────────────────────────────────
    public void beforeInsert(List<SObject> triggerNew) {
        process((List<Contact>) triggerNew, null);
    }

    // ── TriggerAction.BeforeUpdate ─────────────────────────────────────────────
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        process((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    // ───────────────────────────────────────────────────────────────────────────
    private void process(List<Contact> newRecs, List<Contact> oldRecs) {
        if (newRecs == null || newRecs.isEmpty()) return;

        // ---- 1. Identify which records require a duplicate check ----
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        if (oldRecs != null) {
            for (Contact c : oldRecs) {
                oldById.put(c.Id, c);
            }
        }

        List<Contact> toCheck = new List<Contact>();

        for (Contact c : newRecs) {
            // Skip contacts without an Account or without an Email
            if (c.AccountId == null || String.isBlank(c.Email)) continue;

            // On update, skip if neither Email nor AccountId actually changed
            if (oldById.containsKey(c.Id)) {
                Contact old = oldById.get(c.Id);
                if (c.Email == old.Email && c.AccountId == old.AccountId) continue;
            }

            toCheck.add(c);
        }

        if (toCheck.isEmpty()) return;

        // ---- 2. Single SOQL query – find existing contacts with same Account+Email ----
        Set<Id>     acctIds   = new Set<Id>();
        Set<String> emailVals = new Set<String>();

        for (Contact c : toCheck) {
            acctIds.add(c.AccountId);
            emailVals.add(c.Email);
        }

        // Case-insensitive matching: SOQL Email IN is case-insensitive; we also
        // build in-memory keys with toLowerCase() so Apex comparisons are CI too.
        Map<String, Set<Id>> existingByKey = new Map<String, Set<Id>>();

        for (Contact ex : [
            SELECT Id, AccountId, Email
            FROM   Contact
            WHERE  AccountId IN :acctIds
            AND    Email != null
            AND    Email IN :emailVals
        ]) {
            String key = ex.AccountId + '|' + ex.Email.toLowerCase();
            if (!existingByKey.containsKey(key)) {
                existingByKey.put(key, new Set<Id>());
            }
            existingByKey.get(key).add(ex.Id);
        }

        // ---- 3. Walk the trigger list in order; first valid use of a key is accepted ----
        Set<String> batchSeen = new Set<String>();

        for (Contact c : toCheck) {
            String key = c.AccountId + '|' + c.Email.toLowerCase();

            Boolean conflict = false;

            // (a) Conflict with an existing (DB) record – exclude self
            Set<Id> exIds = existingByKey.get(key);
            if (exIds != null) {
                for (Id otherId : exIds) {
                    if (otherId != c.Id) {
                        conflict = true;
                        break;
                    }
                }
            }

            // (b) Conflict with an earlier ACCEPTED record in this same batch
            if (!conflict && batchSeen.contains(key)) {
                conflict = true;
            }

            if (conflict) {
                c.addError(DUP_MSG);
            } else {
                batchSeen.add(key);
            }
        }
    }
}
