public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    /**
     * Tracks Opportunity Ids for which we have already created an "Amount changed" Task
     * within the current transaction. Because TA_Opportunity_RoundAmount (Order 20) re-updates
     * the same Opportunities, the trigger re-enters and this action fires a second time in the
     * same transaction. The guard prevents duplicate Tasks while still allowing one insert DML
     * per trigger execution.
     */
    private static Set<Id> processedOppIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();

        for (SObject s : triggerNew) {
            Opportunity opp = (Opportunity) s;

            // Skip any Opportunity that already received a Task in a prior trigger
            // execution within this transaction (covers the re-entry caused by rounding).
            if (processedOppIds.contains(opp.Id)) {
                continue;
            }

            Opportunity oldOpp = (Opportunity) oldMap.get(opp.Id);
            if (oldOpp != null && opp.Amount != oldOpp.Amount) {
                processedOppIds.add(opp.Id);
                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId  = opp.Id,
                    Status  = 'Completed'
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
